import{_ as o,a as r,b as a}from"./chunks/export-result.B4wpZCeU.js";import{_ as d,o as e,c as n,a2 as s}from"./chunks/framework.Dx-TCpNt.js";const f=JSON.parse('{"title":"导出","description":"导出把一话的分格与笔记变成真能带走的东西：HTML 学习文档、用于幻灯片的 PNG、Word 用户会喜欢的 .docx，以及给 PDF 党准备的打印视图。","frontmatter":{"description":"导出把一话的分格与笔记变成真能带走的东西：HTML 学习文档、用于幻灯片的 PNG、Word 用户会喜欢的 .docx，以及给 PDF 党准备的打印视图。"},"headers":[],"relativePath":"zh/guide/export.md","filePath":"zh/guide/export.md","lastUpdated":1794777339000}'),i={name:"zh/guide/export.md"};function l(h,t,g,c,p,b){return e(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="导出" tabindex="-1">导出 <a class="header-anchor" href="#导出" aria-label="Permalink to &quot;导出&quot;">​</a></h1><p>导出把一话的分格与笔记变成真能带走的东西：HTML 学习文档、用于幻灯片的 PNG、Word 用户会喜欢的 <code>.docx</code>，以及给 PDF 党准备的打印视图。</p><figure class="shot"><img src="'+o+'" alt="导出对话框：版式模板、范围、语言、图片方式与实时预览"><figcaption>导出对话框。左栏用于配置文档；右侧预览版式，拖动分隔线可以调整大小。</figcaption></figure><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>你的笔记在应用里，牢牢挂在分格上。要在平板上复习、打印出来，或把对照结果塞进幻灯片，就需要一个可携带的产物，让页面图片和对应笔记始终待在一起——而且不必上传任何东西。</p><h2 id="打开对话框" tabindex="-1">打开对话框 <a class="header-anchor" href="#打开对话框" aria-label="Permalink to &quot;打开对话框&quot;">​</a></h2><p>按 <code>E</code>，或点击顶栏的 <strong>导出</strong>。对话框总是导出你当前查看的页面或话。</p><h2 id="html-导出" tabindex="-1">HTML 导出 <a class="header-anchor" href="#html-导出" aria-label="Permalink to &quot;HTML 导出&quot;">​</a></h2><h3 id="标题与范围" tabindex="-1">标题与范围 <a class="header-anchor" href="#标题与范围" aria-label="Permalink to &quot;标题与范围&quot;">​</a></h3><table tabindex="0"><thead><tr><th>控件</th><th>作用</th></tr></thead><tbody><tr><td><strong>标题</strong></td><td>文档标题，也用于建议的文件名。</td></tr><tr><td><strong>当前页</strong></td><td>只导出打开的页面。</td></tr><tr><td><strong>整话（n 页）</strong></td><td>导出本话中所有已标注的页面。</td></tr><tr><td><strong>只导出有笔记的页</strong></td><td>跳过没有笔记的页；适合整理学习笔记合集。</td></tr><tr><td><strong>语言</strong></td><td>文档中出现的语言。</td></tr></tbody></table><h3 id="图片方式" tabindex="-1">图片方式 <a class="header-anchor" href="#图片方式" aria-label="Permalink to &quot;图片方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>行为</th></tr></thead><tbody><tr><td><strong>同名 <code>.files</code> 目录</strong>（默认）</td><td>HTML 引用同级文件夹中的图片。体积更小、加载更快。两者要一起复制。</td></tr><tr><td><strong>打包成单文件</strong></td><td>图片以 data URL 内嵌。只分享一个文件，但整话可能达到几十兆字节。</td></tr></tbody></table><p><strong>在原图上标出格子边框</strong> 会把分格矩形叠加到导出的画面上。它与标注无关。</p><p><strong>只导出含这些标签的批注</strong> 按标签筛选笔记；<strong>清除筛选</strong> 取消选择。</p><h3 id="版式" tabindex="-1">版式 <a class="header-anchor" href="#版式" aria-label="Permalink to &quot;版式&quot;">​</a></h3><p>三个内置版式模板：</p><table tabindex="0"><thead><tr><th>模板</th><th>结果</th></tr></thead><tbody><tr><td><strong>左图右注</strong></td><td>漫画页在左，整页与格级笔记在右。</td></tr><tr><td><strong>上图下注</strong></td><td>图片占满宽度，笔记在下方展开。</td></tr><tr><td><strong>分格对照</strong></td><td>每个分格并排展示多种语言，并附该格笔记。</td></tr></tbody></table><p>版式模板可以用自定义名称保存，导出为 JSON 再导入。它们保存在 <code>data/templates/export.json</code>。版式控件包括：</p><table tabindex="0"><thead><tr><th>控件</th><th>效果</th></tr></thead><tbody><tr><td><strong>图栏宽度</strong></td><td>图片栏宽度，按百分比。</td></tr><tr><td><strong>栏目间距</strong></td><td>图片与笔记之间的间距。</td></tr><tr><td><strong>字号</strong></td><td>文档的基础字体缩放。</td></tr><tr><td><strong>每行列数</strong></td><td>每行放置多少个页面块。</td></tr></tbody></table><p>版式会自动记住。你也可以拖动实时预览中的分隔线来设置图片宽度。</p><h3 id="生成" tabindex="-1">生成 <a class="header-anchor" href="#生成" aria-label="Permalink to &quot;生成&quot;">​</a></h3><ol><li>选择范围、语言、图片方式和版式。</li><li>点击 <strong>生成 HTML</strong>。</li><li>完成后，对话框会告诉你导出了多少页、文件写到了哪里。</li><li>用 <strong>打开 HTML</strong> 在浏览器中打开，或用 <strong>下载 HTML</strong> 另存一份。使用默认图片方式时，请一并复制 <code>.files</code> 目录。</li></ol><p>文件写入项目的 <code>exports/</code> 目录。HTML 可以直接从磁盘打开。</p><h3 id="打印" tabindex="-1">打印 <a class="header-anchor" href="#打印" aria-label="Permalink to &quot;打印&quot;">​</a></h3><p>生成的 HTML 包含打印样式：背景被移除，页宽不受限制，页面块不会从图片中间分页。在浏览器中打开文件，用常规 <strong>打印</strong> 命令，通过浏览器打印对话框生成 PDF。</p><div class="tip custom-block"><p class="custom-block-title">打印为 PDF</p><p>在导出对话框选择 <strong>PDF（打印）</strong>，打印视图会带着浏览器打印对话框一起打开，在里面选 <strong>另存为 PDF</strong>。见<a href="#pdf-与-word">PDF 与 Word</a>。</p></div><h2 id="png-导出" tabindex="-1">PNG 导出 <a class="header-anchor" href="#png-导出" aria-label="Permalink to &quot;PNG 导出&quot;">​</a></h2><p><strong>导出 PNG</strong> 区域直接生成图片，不产出文档：</p><table tabindex="0"><thead><tr><th>模式</th><th>内容</th></tr></thead><tbody><tr><td><strong>整页</strong></td><td>整页图片，含分格边框与标注。</td></tr><tr><td><strong>单格</strong></td><td>选中的分格，裁剪并对齐。</td></tr><tr><td><strong>三语拼图</strong></td><td>把所选语言并排放置同一个分格（未选中分格时为整页）。</td></tr></tbody></table><p>选项：</p><ul><li><strong>包含标注（n）</strong> —— 把标注图层画进 PNG。数字表示将包含多少条标注。</li><li>整页与单格 PNG 使用<strong>首选（基准）语言</strong>；拼图使用所选的对照语言。</li><li>未在工作台选中分格时，<strong>单格</strong> 不可用。</li></ul><p>PNG 在浏览器中生成，落在浏览器的下载目录。可以直接粘贴到幻灯片、文档或聊天窗口。</p><figure class="shot"><img src="'+r+'" alt="导出对话框：范围、语言选择、图片方式、PNG 模式与版式滑块"><figcaption>导出对话框中的 PNG 模式。整页和单格使用首选（基准）语言；三语拼图使用所选的对照语言。</figcaption></figure><h2 id="pdf-与-word" tabindex="-1">PDF 与 Word <a class="header-anchor" href="#pdf-与-word" aria-label="Permalink to &quot;PDF 与 Word&quot;">​</a></h2><p>导出对话框有三种输出格式：<strong>HTML</strong>、<strong>Word 文档</strong>、<strong>PDF（打印）</strong>。</p><h3 id="word-docx" tabindex="-1">Word（<code>.docx</code>） <a class="header-anchor" href="#word-docx" aria-label="Permalink to &quot;Word（`.docx`）&quot;">​</a></h3><ol><li>按 <code>E</code>，选择 <strong>Word 文档</strong>。</li><li>照常设置范围、语言和笔记标签筛选。</li><li>点击 <strong>生成 Word</strong>，再点 <strong>下载 .docx</strong>。</li></ol><p>文档会保留页面图片，并把整页笔记和格级笔记转成可编辑的 Word 文本。<strong>标注暂不写入 <code>.docx</code></strong>；需要标注时请用 PNG 或 HTML 导出。</p><h3 id="pdf-打印" tabindex="-1">PDF（打印） <a class="header-anchor" href="#pdf-打印" aria-label="Permalink to &quot;PDF（打印）&quot;">​</a></h3><ol><li>选择 <strong>PDF（打印）</strong>，点击 <strong>生成打印页</strong>。</li><li>打印视图会在新标签页打开，并同时唤起浏览器打印对话框。</li><li>在打印对话框里选 <strong>另存为 PDF</strong>。</li></ol><p>图片按单页适配，笔记跟随所在页面。背景会被移除，页宽不受限制，页面块也不会从图片中间分页。</p><h3 id="纯文本-markdown" tabindex="-1">纯文本 / Markdown <a class="header-anchor" href="#纯文本-markdown" aria-label="Permalink to &quot;纯文本 / Markdown&quot;">​</a></h3><p>用<strong>复制页面上下文</strong>，或笔记上的<strong>渲染 / 源码</strong>开关；笔记正文就是 Markdown。</p><h2 id="导出模板" tabindex="-1">导出模板 <a class="header-anchor" href="#导出模板" aria-label="Permalink to &quot;导出模板&quot;">​</a></h2><p>导出模板（<code>.mnexp</code>）保存版式与样式设置，便于复用或分享同一种外观。通过侧栏的 <strong>交换文件…</strong> 导出和导入模板。导入的模板会先校验，原文件备份到 <code>data/backups/exchange/</code>。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>HTML 里的图片打不开。</strong> 使用默认模式时，<code>.files</code> 目录必须与 HTML 一起移动。请把两者放在一起。</li><li><strong>单文件导出体积巨大。</strong> 这是预期结果：每张图片都被内嵌。整话请用 <code>.files</code> 模式。</li><li><strong>导出里少了一页。</strong> 它没有笔记且开启了 <strong>只导出有笔记的页</strong>，或者在所选语言下没有图片。</li><li><strong>PNG 里没有分格边框。</strong> PNG 导出使用标注开关；启用 <strong>包含标注</strong>，并记住分格边框来自分格矩形，而不是标注。</li><li><strong>打印输出被裁切。</strong> 把浏览器打印缩放设为“适应页面”，只在需要底色时启用背景图形。</li><li><strong>Word 里版式乱了。</strong> 请粘贴渲染后的 HTML，而不是 Markdown 源码；Word 能保留 HTML 表格和图片，但保留不了两栏拖动的宽度。</li><li><strong>找不到 <code>.docx</code> 或 PDF 按钮。</strong> 两者都在导出对话框里：先选 <strong>Word 文档</strong> 或 <strong>PDF（打印）</strong>。Word 暂不包含标注。</li><li><strong>输出文件夹不可写。</strong> 在打包的桌面版中，<code>exports/</code> 位于所选的图库文件夹内。</li></ul><figure class="shot"><img src="'+a+'" alt="在浏览器中打开的导出 HTML：左侧是漫画页，右侧是整页与分格笔记"><figcaption>在浏览器中打开的导出 HTML：左侧是漫画页，右侧是整页与分格笔记。</figcaption></figure><h2 id="缺失的截图" tabindex="-1">缺失的截图 <a class="header-anchor" href="#缺失的截图" aria-label="Permalink to &quot;缺失的截图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>图</th><th>用于</th></tr></thead><tbody><tr><td>PNG 模式对比</td><td>整页 / 单格 / 拼图</td></tr><tr><td>导出模板控件</td><td>保存、导入与套用</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/zh/guide/notes">笔记</a> —— 最终进入文档的内容。</li><li><a href="/KomaYomi-docs/zh/guide/project-files">工程文件与格式</a> —— 想把整个工程连图片一起带走时看这里。</li><li><a href="/KomaYomi-docs/zh/guide/shortcuts">键盘快捷键</a> —— <code>E</code> 打开这个对话框。</li></ul>',52)])])}const m=d(i,[["render",l]]);export{f as __pageData,m as default};
